import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"原理总览","description":"微前端的五个核心问题：加载、隔离、路由、通信、治理。","frontmatter":{"title":"原理总览","description":"微前端的五个核心问题：加载、隔离、路由、通信、治理。"},"headers":[],"relativePath":"principles/index.md","filePath":"principles/index.md","lastUpdated":1792674288000}'),d={name:"principles/index.md"};function r(i,a,l,o,p,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="原理总览" tabindex="-1">原理总览 <a class="header-anchor" href="#原理总览" aria-label="Permalink to &quot;原理总览&quot;">​</a></h1><p>七种方案看起来差异很大，但拆开看，都在处理五个问题。把这五个问题想清楚，任何新方案都能快速上手。</p><h2 id="五个核心问题" tabindex="-1">五个核心问题 <a class="header-anchor" href="#五个核心问题" aria-label="Permalink to &quot;五个核心问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>关键点</th><th>对应章节</th></tr></thead><tbody><tr><td>加载</td><td>HTML Entry、模块加载、资源解析、CORS</td><td><a href="/micro-frontend-docs/principles/html-entry">HTML Entry</a></td></tr><tr><td>隔离</td><td>JS 沙箱、样式隔离、DOM 边界</td><td><a href="/micro-frontend-docs/principles/sandbox">JS 沙箱</a>、<a href="/micro-frontend-docs/principles/style-isolation">样式隔离</a></td></tr><tr><td>路由</td><td>URL 归属、路由劫持、刷新恢复</td><td><a href="/micro-frontend-docs/principles/routing">路由</a></td></tr><tr><td>通信</td><td>props、全局状态、事件总线、postMessage</td><td><a href="/micro-frontend-docs/principles/communication">通信</a></td></tr><tr><td>治理</td><td>版本、灰度、监控、回滚、安全</td><td><a href="/micro-frontend-docs/advanced/">工程化</a></td></tr></tbody></table><h2 id="一张全局图" tabindex="-1">一张全局图 <a class="header-anchor" href="#一张全局图" aria-label="Permalink to &quot;一张全局图&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────── 主应用（基座） ────────────────────────┐</span></span>
<span class="line"><span>│  路由调度  │  加载器  │  沙箱  │  样式隔离  │  通信  │  监控    │</span></span>
<span class="line"><span>└──────┬──────────┬─────────┬──────────┬──────────┬──────────┘</span></span>
<span class="line"><span>       │          │         │          │          │</span></span>
<span class="line"><span>   ┌───▼───┐  ┌───▼───┐ ┌───▼───┐  ┌───▼───┐  ┌───▼───┐</span></span>
<span class="line"><span>   │订单应用│  │商品应用│ │客户应用│  │报表应用│  │老系统 │</span></span>
<span class="line"><span>   └───────┘  └───────┘ └───────┘  └───────┘  └───────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>主应用不一定“大”，它更像一个<strong>运行时容器 + 治理中心</strong>。</p><h2 id="加载-三种形态" tabindex="-1">加载：三种形态 <a class="header-anchor" href="#加载-三种形态" aria-label="Permalink to &quot;加载：三种形态&quot;">​</a></h2><h3 id="_1-文档级加载-iframe" tabindex="-1">1. 文档级加载（iframe） <a class="header-anchor" href="#_1-文档级加载-iframe" aria-label="Permalink to &quot;1. 文档级加载（iframe）&quot;">​</a></h3><p>浏览器直接创建新文档，天然完成 HTML、JS、CSS 的加载与执行。</p><h3 id="_2-html-entry-qiankun" tabindex="-1">2. HTML Entry（qiankun） <a class="header-anchor" href="#_2-html-entry-qiankun" aria-label="Permalink to &quot;2. HTML Entry（qiankun）&quot;">​</a></h3><p>主应用 <code>fetch</code> 子应用 HTML，解析出脚本与样式，再手动执行。好处是子应用只需提供 URL。</p><h3 id="_3-模块级加载-module-federation、web-components" tabindex="-1">3. 模块级加载（Module Federation、Web Components） <a class="header-anchor" href="#_3-模块级加载-module-federation、web-components" aria-label="Permalink to &quot;3. 模块级加载（Module Federation、Web Components）&quot;">​</a></h3><p>直接 <code>import</code> 远程模块或加载自定义元素脚本，不涉及页面 HTML。</p><h2 id="隔离-没有免费的午餐" tabindex="-1">隔离：没有免费的午餐 <a class="header-anchor" href="#隔离-没有免费的午餐" aria-label="Permalink to &quot;隔离：没有免费的午餐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>隔离对象</th><th>iframe</th><th>Proxy 沙箱</th><th>Shadow DOM</th><th>无隔离</th></tr></thead><tbody><tr><td>全局变量</td><td>强</td><td>强</td><td>弱</td><td>无</td></tr><tr><td>原型链</td><td>强</td><td>中</td><td>弱</td><td>无</td></tr><tr><td>定时器</td><td>强</td><td>中</td><td>弱</td><td>无</td></tr><tr><td>样式</td><td>强</td><td>无</td><td>强</td><td>无</td></tr><tr><td>DOM 查询</td><td>强</td><td>弱</td><td>中</td><td>无</td></tr><tr><td>通信成本</td><td>高</td><td>低</td><td>低</td><td>低</td></tr></tbody></table><p>实际选型时，要先明确“必须隔离什么”。例如后台系统通常最怕样式污染，而不是全局变量。</p><h2 id="路由-谁拥有-url" tabindex="-1">路由：谁拥有 URL <a class="header-anchor" href="#路由-谁拥有-url" aria-label="Permalink to &quot;路由：谁拥有 URL&quot;">​</a></h2><p>三种常见模式：</p><ol><li><strong>主应用拥有路由</strong>：qiankun、single-spa 通过 <code>activeRule</code> 匹配路径。</li><li><strong>子应用拥有路由</strong>：micro-app 的 <code>baseroute</code>、qiankun 的 <code>activeRule + 子应用 history</code>。</li><li><strong>iframe 内独立路由</strong>：主应用无法直接控制，需要 URL 同步。</li></ol><p>路由设计的关键是：<strong>刷新页面后，能否恢复到同一个子应用状态</strong>。</p><h2 id="通信-按耦合度排序" tabindex="-1">通信：按耦合度排序 <a class="header-anchor" href="#通信-按耦合度排序" aria-label="Permalink to &quot;通信：按耦合度排序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>props（最弱耦合）</span></span>
<span class="line"><span>  → 全局状态（主应用主导）</span></span>
<span class="line"><span>    → 事件总线（发布订阅）</span></span>
<span class="line"><span>      → postMessage（跨上下文）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>原则：</p><ul><li>能用 props 就不用全局状态。</li><li>能用事件就不用共享对象。</li><li>跨 iframe 必须用 <code>postMessage</code>，并校验 <code>origin</code>。</li></ul><p>详见<a href="/micro-frontend-docs/principles/communication">通信机制</a>。</p><h2 id="治理-决定能不能上线" tabindex="-1">治理：决定能不能上线 <a class="header-anchor" href="#治理-决定能不能上线" aria-label="Permalink to &quot;治理：决定能不能上线&quot;">​</a></h2><p>Demo 与生产的差距，主要在治理：</p><ul><li>子应用版本与主应用兼容矩阵。</li><li>灰度与回滚。</li><li>错误上报与 Source Map。</li><li>性能预算与缓存策略。</li><li>安全边界与依赖审计。</li></ul><p>从<a href="/micro-frontend-docs/advanced/">工程化总览</a>开始。</p><h2 id="怎么用这组原理" tabindex="-1">怎么用这组原理 <a class="header-anchor" href="#怎么用这组原理" aria-label="Permalink to &quot;怎么用这组原理&quot;">​</a></h2><p>读每个方案页时，带着五个问题去看：</p><ol><li>它怎么加载子应用？</li><li>它隔离了什么，没隔离什么？</li><li>路由归谁管？</li><li>通信用什么机制？</li><li>生产上还需要补什么？</li></ol><p>能答出这五题，就算真正理解了一个方案。</p>`,34)])])}const b=t(d,[["render",r]]);export{u as __pageData,b as default};
